solution.solution.cpp:
int nextId()
{
    static int id{ 0 };
    ++id;
    return id;
}

unitTests:
TEST("counts up across calls") {
    CHECK_EQ(nextId(), 1);
    CHECK_EQ(nextId(), 2);
    CHECK_EQ(nextId(), 3);
    for (int i{ 0 }; i < 10; ++i) nextId();
    CHECK_EQ(nextId(), 14);
}

